import{_ as o,o as a,c as t,ag as i}from"./chunks/framework.DEqXEGcv.js";const p=JSON.parse('{"title":"thegent Troubleshooting Guide","description":"","frontmatter":{},"headers":[],"relativePath":"guides/TROUBLESHOOTING.md","filePath":"guides/TROUBLESHOOTING.md","lastUpdated":1771159865000}'),r={name:"guides/TROUBLESHOOTING.md"};function n(s,e,d,l,c,u){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="thegent-troubleshooting-guide" tabindex="-1">thegent Troubleshooting Guide <a class="header-anchor" href="#thegent-troubleshooting-guide" aria-label="Permalink to &quot;thegent Troubleshooting Guide&quot;">​</a></h1><p>Common issues and solutions for developing and running <code>thegent</code>.</p><h2 id="_1-environment-issues" tabindex="-1">1. Environment Issues <a class="header-anchor" href="#_1-environment-issues" aria-label="Permalink to &quot;1. Environment Issues&quot;">​</a></h2><h3 id="command-not-found-task" tabindex="-1"><code>command not found: task</code> <a class="header-anchor" href="#command-not-found-task" aria-label="Permalink to &quot;`command not found: task`&quot;">​</a></h3><p>Install Go Task: <code>brew install go-task</code>.</p><h3 id="direnv-not-loading" tabindex="-1"><code>direnv</code> not loading <a class="header-anchor" href="#direnv-not-loading" aria-label="Permalink to &quot;`direnv` not loading&quot;">​</a></h3><p>Ensure <code>direnv</code> is installed and hooked into your shell. Run <code>direnv allow</code> in the project root.</p><h3 id="python-version-mismatch" tabindex="-1">Python version mismatch <a class="header-anchor" href="#python-version-mismatch" aria-label="Permalink to &quot;Python version mismatch&quot;">​</a></h3><p><code>thegent</code> requires Python 3.12+. Use <code>uv venv --python 3.12</code> to create a compatible environment.</p><h2 id="_2-cliproxyapiplus-proxy" tabindex="-1">2. CLIProxyAPIPlus Proxy <a class="header-anchor" href="#_2-cliproxyapiplus-proxy" aria-label="Permalink to &quot;2. CLIProxyAPIPlus Proxy&quot;">​</a></h2><h3 id="proxy-fails-to-start" tabindex="-1">Proxy fails to start <a class="header-anchor" href="#proxy-fails-to-start" aria-label="Permalink to &quot;Proxy fails to start&quot;">​</a></h3><p>Check if the port (default 8317) is already in use: <code>lsof -i :8317</code>. Ensure the binary is in your PATH or <code>THGENT_CLIPROXY_BINARY</code> is set correctly in <code>.env</code>.</p><h3 id="authentication-failures" tabindex="-1">Authentication Failures <a class="header-anchor" href="#authentication-failures" aria-label="Permalink to &quot;Authentication Failures&quot;">​</a></h3><p>Run <code>thegent login &lt;provider&gt;</code> to re-authenticate. Tokens are stored in <code>~/.cli-proxy-api</code>.</p><h2 id="_3-mcp-issues" tabindex="-1">3. MCP Issues <a class="header-anchor" href="#_3-mcp-issues" aria-label="Permalink to &quot;3. MCP Issues&quot;">​</a></h2><h3 id="cursor-cannot-connect-to-mcp" tabindex="-1">Cursor cannot connect to MCP <a class="header-anchor" href="#cursor-cannot-connect-to-mcp" aria-label="Permalink to &quot;Cursor cannot connect to MCP&quot;">​</a></h3><ol><li>Ensure the server is running: <code>task dev</code>.</li><li>Verify the health endpoint: <code>curl http://127.0.0.1:3847/health</code>.</li><li>Check <code>.cursor/mcp.json</code> for correct URL.</li></ol><h2 id="_4-quality-gate-failures" tabindex="-1">4. Quality Gate Failures <a class="header-anchor" href="#_4-quality-gate-failures" aria-label="Permalink to &quot;4. Quality Gate Failures&quot;">​</a></h2><h3 id="dx-audit-failures-module-size" tabindex="-1">DX Audit Failures (Module Size) <a class="header-anchor" href="#dx-audit-failures-module-size" aria-label="Permalink to &quot;DX Audit Failures (Module Size)&quot;">​</a></h3><p>If <code>scripts/dx-audit.sh</code> fails due to module size, you <strong>must</strong> refactor and decompose the large file. See <code>WARP.md</code> for decomposition patterns.</p><h3 id="architectural-boundary-violation" tabindex="-1">Architectural Boundary Violation <a class="header-anchor" href="#architectural-boundary-violation" aria-label="Permalink to &quot;Architectural Boundary Violation&quot;">​</a></h3><p>If <code>tach check</code> fails, you have introduced an illegal import. Refer to <code>docs/ARCHITECTURE_LAYERS.md</code> for the allowed dependency graph.</p>',22)])])}const m=o(r,[["render",n]]);export{p as __pageData,m as default};
